# Extract user messages from today's large session transcripts (first user turns)
$sessions = @(
  @{path="C:\Users\Administrator\.claude\projects\E--project-temu\2fcab51f-d98e-4a95-a0bd-c99cd9b9b50b.jsonl"; name="temu"},
  @{path="C:\Users\Administrator\.claude\projects\E--project----\a5f6b079-d781-44e6-bc95-ed50ac1f83f7.jsonl"; name="haiwaicang"},
  @{path="C:\Users\Administrator\.claude\projects\E--project----\46598195-889d-4e1a-8232-fd07e62c1d37.jsonl"; name="haiwaicang2"},
  @{path="C:\Users\Administrator\.claude\projects\E--project------------\83c76ba2-5ad6-49c0-927f-2394e2175e1f.jsonl"; name="qingquan"},
  @{path="C:\Users\Administrator\.claude\projects\E--project---\c3e2f8c9-61d6-4d17-838c-a24258fea1c7.jsonl"; name="ribao"}
)
foreach ($s in $sessions) {
  Write-Host "`n======== $($s.name) ========"
  if (-not (Test-Path $s.path)) { Write-Host "missing"; continue }
  $fi = Get-Item $s.path
  Write-Host "size=$($fi.Length) mtime=$($fi.LastWriteTime)"
  # Use python or node to parse jsonl for user messages - use powershell carefully
  $count = 0
  Get-Content $s.path -Encoding UTF8 -TotalCount 200 | ForEach-Object {
    if ($count -ge 25) { return }
    try {
      $obj = $_ | ConvertFrom-Json -ErrorAction Stop
      $role = $null; $text = $null
      if ($obj.type -eq 'user' -or $obj.role -eq 'user' -or $obj.message.role -eq 'user') {
        if ($obj.message.content) {
          if ($obj.message.content -is [string]) { $text = $obj.message.content }
          elseif ($obj.message.content[0].text) { $text = $obj.message.content[0].text }
          elseif ($obj.message.content[0].content) { $text = $obj.message.content[0].content }
        } elseif ($obj.content) {
          if ($obj.content -is [string]) { $text = $obj.content }
          elseif ($obj.content[0].text) { $text = $obj.content[0].text }
        }
        if ($text -and $text.Length -gt 5 -and $text -notmatch '^<.*command' -and $text -notmatch 'tool_result|system-reminder') {
          $snippet = ($text -replace '\s+',' ').Substring(0, [Math]::Min(300, ($text -replace '\s+',' ').Length))
          Write-Host ("U: " + $snippet)
          $count++
        }
      }
    } catch {}
  }
}

# Check history.jsonl for today's user commands related to these projects
$hist = "C:\Users\Administrator\.claude\history.jsonl"
$start = (Get-Date "2026-07-30").Date
# history may not have timestamps as file mtime - parse
$lines = Get-Content $hist -Tail 80 -Encoding UTF8 -ErrorAction SilentlyContinue
foreach ($line in $lines) {
