    $o = $line | ConvertFrom-Json
    $ts = $null
    if ($o.timestamp) { $ts = $o.timestamp } elseif ($o.time) { $ts = $o.time } elseif ($o.ts) { $ts = $o.ts }
    $disp = if ($o.display) { $o.display } elseif ($o.project) { $o.project } else { "" }
    $msg = if ($o.display) { $o.display } elseif ($o.message) { $o.message } elseif ($o.text) { $o.text } elseif ($o.prompt) { $o.prompt } else { ($o | ConvertTo-Json -Compress).Substring(0,[Math]::Min(200,($o|ConvertTo-Json -Compress).Length)) }
