if (Test-Path "E:\project\清泉跨境系统（企业级）\.grok") {
  Get-ChildItem "E:\project\清泉跨境系统（企业级）\.grok" -Recurse -ErrorAction SilentlyContinue | Sort-Object LastWriteTime -Descending | Select-Object -First 20 FullName, LastWriteTime
}

# Grok sessions today for the four projects
$base = "C:\Users\Administrator\.grok\sessions"
Get-ChildItem $base -Directory -ErrorAction SilentlyContinue | ForEach-Object {
  $proj = [uri]::UnescapeDataString($_.Name)
  $today = Get-ChildItem $_.FullName -Recurse -File -ErrorAction SilentlyContinue | Where-Object { $_.LastWriteTime -ge (Get-Date "2026-07-30").Date }
  if ($today) {
    Write-Host "`n==== $proj ===="
    $today | Sort-Object LastWriteTime -Descending | Select-Object -First 15 @{n='Rel';e={$_.FullName.Replace($_.DirectoryName+'\','')}}, LastWriteTime, Length | Format-Table -AutoSize
    # try read summary json
    Get-ChildItem $_.FullName -Directory -ErrorAction SilentlyContinue | Where-Object { $_.LastWriteTime -ge (Get-Date "2026-07-30").Date } | ForEach-Object {
      $sum = Join-Path $_.FullName "session_summary.json"
      $info = Join-Path $_.FullName "session.json"
      foreach ($f in @($sum, $info, (Join-Path $_.FullName "summary.json"))) {
        if (Test-Path $f) {
          Write-Host "FILE $f"
          Get-Content $f -TotalCount 30 -Encoding UTF8 -ErrorAction SilentlyContinue
        }
      }
      # list files in session
      Get-ChildItem $_.FullName -File | Select-Object Name, Length, LastWriteTime | Format-Table -AutoSize
    }
